diff --git a/daemon/actions/bundled/refreshrate.cpp b/daemon/actions/bundled/refreshrate.cpp
new file mode 100644
index 000000000..1bb08105a
--- /dev/null
+++ b/daemon/actions/bundled/refreshrate.cpp
@@ -0,0 +1,148 @@
+/*
+ *   SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+ *
+ *   SPDX-License-Identifier: GPL-2.0-or-later
+ */
+
+#include "refreshrate.h"
+
+#include <PowerDevilProfileSettings.h>
+#include <powerdevil_debug.h>
+
+#include <KConfigGroup>
+#include <KPluginFactory>
+#include <KSharedConfig>
+
+#include <KScreen/Config>
+#include <KScreen/ConfigMonitor>
+#include <KScreen/GetConfigOperation>
+#include <KScreen/Mode>
+#include <KScreen/Output>
+#include <KScreen/SetConfigOperation>
+
+#include <cmath>
+
+K_PLUGIN_CLASS_WITH_JSON(PowerDevil::BundledActions::RefreshRate, "powerdevilrefreshrateaction.json")
+
+using namespace Qt::StringLiterals;
+
+// don't go below 60 Hz, or 59.94 Hz for screens that only offer that
+static constexpr float s_minRefreshRate = 59.0;
+
+static int milliHertz(const KScreen::ModePtr &mode)
+{
+    return std::lround(mode->refreshRate() * 1000);
+}
+
+// remembers the modes we changed, so they're restored even after a restart
+static KConfigGroup loweredOutputs()
+{
+    return KSharedConfig::openStateConfig()->group(u"LoweredRefreshRates"_s);
+}
+
+namespace PowerDevil::BundledActions
+{
+RefreshRate::RefreshRate(QObject *parent)
+    : Action(parent)
+{
+    auto op = new KScreen::GetConfigOperation(KScreen::GetConfigOperation::NoEDID, this);
+    connect(op, &KScreen::ConfigOperation::finished, this, [this](KScreen::ConfigOperation *configOp) {
+        if (configOp->hasError()) {
+            return;
+        }
+        m_config = static_cast<KScreen::GetConfigOperation *>(configOp)->config();
+        KScreen::ConfigMonitor::instance()->addConfig(m_config);
+        apply();
+    });
+}
+
+bool RefreshRate::loadAction(const PowerDevil::ProfileSettings &profileSettings)
+{
+    m_lower = profileSettings.lowerRefreshRate();
+    apply();
+    return m_lower;
+}
+
+void RefreshRate::apply()
+{
+    if (!m_config) {
+        return;
+    }
+    if (m_lower) {
+        lowerRefreshRates();
+    } else {
+        restoreRefreshRates();
+    }
+}
+
+void RefreshRate::lowerRefreshRates()
+{
+    KConfigGroup lowered = loweredOutputs();
+    bool changed = false;
+    for (const KScreen::OutputPtr &output : m_config->outputs()) {
+        const KScreen::ModePtr current = output->currentMode();
+        if (!output->isConnected() || !output->isEnabled() || !current) {
+            continue;
+        }
+        KScreen::ModePtr lowest;
+        for (const KScreen::ModePtr &mode : output->modes()) {
+            if (mode->size() == current->size() && mode->refreshRate() >= s_minRefreshRate && milliHertz(mode) < milliHertz(current)
+                && (!lowest || mode->refreshRate() < lowest->refreshRate())) {
+                lowest = mode;
+            }
+        }
+        if (!lowest) {
+            continue;
+        }
+        qCDebug(POWERDEVIL) << "RefreshRate: lowering" << output->name() << "from" << current->refreshRate() << "to" << lowest->refreshRate();
+        KConfigGroup group = lowered.group(output->name());
+        group.writeEntry("Size", current->size());
+        group.writeEntry("RefreshRate", milliHertz(current));
+        group.writeEntry("LoweredRefreshRate", milliHertz(lowest));
+        output->setCurrentModeId(lowest->id());
+        changed = true;
+    }
+    if (changed) {
+        lowered.sync();
+        new KScreen::SetConfigOperation(m_config, this);
+    }
+}
+
+void RefreshRate::restoreRefreshRates()
+{
+    KConfigGroup lowered = loweredOutputs();
+    bool changed = false;
+    for (const KScreen::OutputPtr &output : m_config->outputs()) {
+        KConfigGroup group = lowered.group(output->name());
+        if (!group.exists() || !output->isConnected() || !output->isEnabled()) {
+            continue;
+        }
+        const QSize size = group.readEntry("Size", QSize());
+        const int refreshRate = group.readEntry("RefreshRate", 0);
+        const int loweredRefreshRate = group.readEntry("LoweredRefreshRate", 0);
+        group.deleteGroup();
+
+        // leave it alone if the mode was changed by someone else in the meantime
+        const KScreen::ModePtr current = output->currentMode();
+        if (!current || current->size() != size || milliHertz(current) != loweredRefreshRate) {
+            continue;
+        }
+        for (const KScreen::ModePtr &mode : output->modes()) {
+            if (mode->size() == size && milliHertz(mode) == refreshRate) {
+                qCDebug(POWERDEVIL) << "RefreshRate: restoring" << output->name() << "to" << mode->refreshRate();
+                output->setCurrentModeId(mode->id());
+                changed = true;
+                break;
+            }
+        }
+    }
+    lowered.sync();
+    if (changed) {
+        new KScreen::SetConfigOperation(m_config, this);
+    }
+}
+}
+
+#include "refreshrate.moc"
+
+#include "moc_refreshrate.cpp"
