+    explicit RefreshRate(QObject *parent);
+
+    bool loadAction(const PowerDevil::ProfileSettings &profileSettings) override;
+
+private:
+    void apply();
+    void lowerRefreshRates();
+    void restoreRefreshRates();
+
+    KScreen::ConfigPtr m_config;
+    bool m_lower = false;
+};
+
+}
